var EnergirComputerEquipment = Class.create();
EnergirComputerEquipment.prototype = Object.extendsObject(AbstractAjaxProcessor, {

Computerequipmentloan: function() {
    var datedesired = new GlideDateTime(this.getParameter('sysparm_desireddate'));
    var dateretour = new GlideDateTime(this.getParameter('sysparm_returndate'));

    var desiredMillis = datedesired.getNumericValue();
    var returnMillis = dateretour.getNumericValue();

    var choices = [];
    var choiceF = new GlideRecord('question_choice');
    choiceF.addEncodedQuery('question=7208afed87f5ce10124b7777dabb3573^inactive=false^ORDERBYorder');
    choiceF.query();
    while (choiceF.next()) {
        choices.push(choiceF.text.toString());
    }

    var gr = new GlideRecord('x_1610537_rbh_cust_u_catalog_variables');
    gr.addEncodedQuery('ritm_cat_item=1d64232987f5ce10124b7777dabb35df^optn_item_option_new=7208afed87f5ce10124b7777dabb3573^ORoptn_item_option_new=3817276d87f5ce10124b7777dabb3560^ORoptn_item_option_new=3f87e36d87f5ce10124b7777dabb3522');
    gr.query();

    while (gr.next()) {
        var gitem = new GlideRecord('u_catalog_variables');
        gitem.addEncodedQuery('optn_item_option_new=3f87e36d87f5ce10124b7777dabb3522^mtom_request_item=' + gr.mtom_request_item); 
        gitem.query();

        var gitemreturn = new GlideRecord('u_catalog_variables');
        gitemreturn.addEncodedQuery('optn_item_option_new=3817276d87f5ce10124b7777dabb3560^mtom_request_item=' + gr.mtom_request_item);
        gitemreturn.query(); 

        if (gitem.next() && gitemreturn.next()) {
            var returndateItem = new GlideDateTime(gitem.optn_value).getNumericValue();
            var desireddateItem = new GlideDateTime(gitemreturn.optn_value).getNumericValue();

            var overlap = (desiredMillis < returndateItem && returnMillis > desireddateItem);

            if (overlap) {
                var indexToRemove = choices.indexOf(gr.optn_value.toString());
                if (indexToRemove !== -1) {
                    choices.splice(indexToRemove, 1);
                }
            }
        }
    }

    return JSON.stringify(choices);
},


